def split_path(path):
    out = []
    cur = ""
    in_quotes = False
    for ch in path:
        if ch == '"':
            in_quotes = not in_quotes
        elif ch == "/" and not in_quotes:
            if cur:
                out.append(cur)
            cur = ""
        else:
            cur += ch
    if cur:
        out.append(cur)
    return out

